"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7650],{54487:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"TechTreeGuiController","desc":"Binds the Studio-authored `StarterGui.TechTreeGui` to the Research backend.\\nUnlike the controller it replaces, this one **never builds GUI** \u2014 every card,\\nconnector line, and panel is authored in Studio, and each node\'s\\n`ResearchConfig.GuiPath` names the card it drives. Node names and durations are\\nwritten from config so the authored labels can never drift from the real values.\\nCard and line colours come from `ResearchConfig.NodeStateColors`.","realm":["Client"],"source":{"line":13,"path":"src/StarterPlayer/StarterPlayerScripts/TechTreeGuiController.client.luau"}}')}}]);